/**
 * Loads the bundled Noto faces (public/fonts, generated by `npm run fonts`). @remotion/fonts delays
 * the render until every face is ready, so the first frame never uses a fallback font.
 */
import { loadFont } from '@remotion/fonts';
import { staticFile } from 'remotion';
import faces from '../catalog/fonts.json';

let loaded: Promise<unknown> | undefined;

export const loadBundledFonts = (): Promise<unknown> => {
  loaded ??= Promise.all(
    faces.map((f) =>
      loadFont({
        family: f.family,
        url: staticFile(`fonts/${f.file}`),
        weight: String(f.weight),
        unicodeRange: f.unicodeRange,
        format: 'woff2',
      }),
    ),
  );
  return loaded;
};
